# v10-patch.ps1 - perapihan Arus Global (HP + desktop): ganti blok v9 di tools\v8.js dan public\index.html
$ErrorActionPreference = 'Stop'
Set-Location 'E:\0\MAB Project\MAB-Terminal\mab-terminal'
$b64 = ''
$blk = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($b64)).Replace("`r`n","`n").TrimEnd()
$jsPath = (Resolve-Path 'tools\v8.js').Path
$htPath = (Resolve-Path 'public\index.html').Path
$js = [IO.File]::ReadAllText($jsPath).Replace("`r`n","`n")
$ht = [IO.File]::ReadAllText($htPath).Replace("`r`n","`n")
if ($js.Contains('/* ---- Arus Global v10:')) { 'v10 sudah terpasang. Tidak ada yang diubah.'; return }
function Rep([string]$t,[string]$old,[string]$new){
  $n = ([regex]::Matches($t,[regex]::Escape($old))).Count
  if ($n -ne 1) { throw "Anchor harus cocok tepat 1 kali, ditemukan $n : $old" }
  return $t.Replace($old,$new)
}
$s = $js.IndexOf('/* ---- Arus Global v9:')
$e = $js.IndexOf('const PAGES={')
if ($s -lt 0) { throw 'Blok v9 tidak ditemukan di v8.js (jalankan v9-patch.ps1 dulu)' }
if ($e -le $s) { throw 'Urutan blok tidak sesuai' }
$js2 = $js.Substring(0,$s) + $blk + "`n" + $js.Substring($e)
$js2 = Rep $js2 "ftf:'m15'}" "ftf:'m15',fxn:false}"
$js2 = Rep $js2 "window.v7={ftf:k=>" "window.v7={fxn:o=>{NV.fxn=o},ftf:k=>"
if ($js2.Contains('</script>')) { throw 'Kode baru mengandung </script>' }
$tag = '<script id="v8-js">'
$i = $ht.IndexOf($tag); if ($i -lt 0) { throw 'Tag v8-js tidak ditemukan di index.html' }
$a = $i + $tag.Length
$z = $ht.IndexOf('</script>',$a); if ($z -lt 0) { throw 'Penutup </script> tidak ditemukan' }
$old = $ht.Substring($a,$z-$a)
if ($old.Trim() -ne $js.Trim()) { throw 'Blok v8-js di index.html TIDAK sama dengan tools\v8.js. Tidak ada yang diubah.' }
$lead = $old.Substring(0,$old.Length-$old.TrimStart().Length)
$trail = $old.Substring($old.TrimEnd().Length)
$ht2 = $ht.Substring(0,$a) + $lead + $js2.Trim() + $trail + $ht.Substring($z)
Copy-Item $jsPath "$env:TEMP\v8.js.v10.bak" -Force
Copy-Item $htPath "$env:TEMP\index.html.v10.bak" -Force
$u8 = New-Object Text.UTF8Encoding($false)
[IO.File]::WriteAllText($jsPath,$js2,$u8)
[IO.File]::WriteAllText($htPath,$ht2,$u8)
"v8.js: $((Get-Item $jsPath).Length) byte; index.html: $((Get-Item $htPath).Length) byte"
"fxSankey di v8.js: $(([regex]::Matches([IO.File]::ReadAllText($jsPath),'function fxSankey')).Count); di index.html: $(([regex]::Matches([IO.File]::ReadAllText($htPath),'function fxSankey')).Count)"
if (Get-Command node -ErrorAction SilentlyContinue) { node --check $jsPath; "node --check v8.js: kode keluar $LASTEXITCODE" }
'Selesai.'
